public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    long [] a = new long[n];

    for(int i=0; i<n; i++)
    {
        a[i] = sc.nextLong();
    }

    sc.close();
    long X = (long)Math.sqrt(n) + 1; // Adjust X to ensure proper indexing
    long [] dp = new long[n];
    long [][] lazy = new long[n][(int)X+1]; // Second index just means the speed
    dp[0] = 1;



    for(int i=0; i<n; i++)
    {
        for(int j=0; j<=X; j++) // Ensure all speeds are considered
        {
            dp[i] = (dp[i] + lazy[i][j])%mod;
        }

        for(int j=0; j<=X; j++)
        {
                if(i+j<n)
                {
                    lazy[i+j][j] = (lazy[i+j][j] + lazy[i][j])%mod;
                }

        }

        if(a[i]>X)
        {
            for(int j=i+(int)a[i]; j<n && j<=i+(int)a[i]*X; j+=a[i]) // Ensure moves do not exceed bounds
            {
                dp[j] = (dp[j] + dp[i])%mod;
            }
        }
        else{
            if(i+(int)a[i]<n)
            {
                lazy[i+(int)a[i]][(int)a[i]] = (lazy[i+(int)a[i]][(int)a[i]] + dp[i])%mod; // Corrected the order of addition to ensure proper propagation.
            }
        }


    }

    long ans = 0;

    for(int i=0; i<n; i++) ans= (ans + dp[i])%mod;

    System.out.println(ans);

}
